import { useEffect, useRef, useState } from 'react';
import { useKainBain } from '../../context/KainBainContext';
import { SkillsSection } from './SkillsSection';
import { SelectDropdown } from '../common/SelectDropdown';
import { ProjectSettingsForm } from './ProjectSettingsForm';
import { WorkflowManagementPanel } from './WorkflowManagementPanel';
import { SettingsSearchInput } from './SettingsSearchInput';
import { AddressesSection } from './AddressesSection';
import {
  PROJECT_SETTINGS_TABS,
  PROJECT_SETTINGS_SECTIONS,
  PROJECT_FORM_SECTIONS,
} from './projectSettingsTabs';

// Re-exported so existing consumers (`ProjectSettings.test.jsx`) keep one
// import site; the tab config itself lives in `projectSettingsTabs.js` where
// `ProjectSettingsForm` shares it without a render-cycle import.
export { PROJECT_SETTINGS_TABS, PROJECT_SETTINGS_SECTIONS, PROJECT_FORM_SECTIONS };

// How the jump-to-setting highlight behaves: a short wait lets the newly
// selected tab render before scrolling, then the ring stays visible briefly
// so the eye lands on the right field before it clears.
const HIGHLIGHT_SHOW_DELAY_MS = 80;
const HIGHLIGHT_HIDE_DELAY_MS = 2100;

/***
 * MARK: ProjectSettings
 * @description A dedicated Project Management / Settings page for configuring
 * the active project across focused tabs — Project (basics + retry/timeouts),
 * Aliases (model aliases), Files & Repos (paths, repos), Addresses (app link) — plus
 * multiple named workflows, and skills.
 * App-wide UI & Workspace customization lives in System Settings
 * (SystemSettingsPage, `/system-settings`). Distinct from that platform-scoped
 * screen, this page is per-project and keeps the `/settings` route.
 * @example <ProjectSettings />
 ***/
export function ProjectSettings() {
  const { projects, activeProjectId, selectProject } = useKainBain();
  const activeProject = projects.find((p) => p.id === activeProjectId);
  const [settingsSection, setSettingsSection] = useState('project');
  // Fail-safe: an unknown section id (e.g. a stale 'ui' from before UI
  // customization moved to System Settings) falls back to the project form
  // instead of rendering a blank page.
  const effectiveSection = PROJECT_SETTINGS_SECTIONS.includes(settingsSection)
    ? settingsSection
    : 'project';
  // Jump-to-setting target: `{ id, at }` so repeating the same search still
  // re-fires the highlight effect below (object identity changes each time).
  // `at` is a monotonic counter (not Date.now()): the value only needs to be
  // unique per selection, and a counter keeps the update pure and testable.
  const [highlightTarget, setHighlightTarget] = useState(null);
  const highlightSeqRef = useRef(0);
  // Fail-safe: `effectiveSection` is always a known tab, but the lookup still
  // falls back to the first tab so a heading always renders (never blank).
  const activeTab =
    PROJECT_SETTINGS_TABS.find((tab) => tab.id === effectiveSection) ?? PROJECT_SETTINGS_TABS.at(0);
  // Unsaved-edits flag reported by the shared project form.
  const [formDirty, setFormDirty] = useState(false);
  // Focus targets for arrow-key tab navigation (automatic activation: moving
  // focus also selects the tab, matching the APG tabs pattern).
  const tabButtonRefs = useRef([]);
  /***
   * MARK: handleSectionChange
   * @description Tab switch guard: leaving the project-related tabs
   *   (Project/Aliases/Files & Repos/Addresses) with unsaved edits asks for
   *   confirmation first. Moving between project tabs never warns — the
   *   shared form stays mounted and keeps the edits.
   ***/
  const handleSectionChange = (nextSection) => {
    // Fail-safe: an unknown section id is ignored, never stored — storing it
    // would only be masked by the effectiveSection fallback and would hide
    // the bad caller. Returns whether the switch was accepted so callers
    // (arrow-key focus, search highlight) only follow a switch that happened.
    if (!PROJECT_SETTINGS_SECTIONS.includes(nextSection)) return false;
    if (
      formDirty &&
      PROJECT_FORM_SECTIONS.includes(effectiveSection) &&
      !PROJECT_FORM_SECTIONS.includes(nextSection) &&
      typeof window !== 'undefined' &&
      typeof window.confirm === 'function' &&
      !window.confirm('You have unsaved changes. Switch tabs anyway?')
    ) {
      return false;
    }
    setSettingsSection(nextSection);
    return true;
  };
  const focusTabAt = (index) => {
    const count = PROJECT_SETTINGS_TABS.length;
    if (count === 0) return;
    const wrapped = ((index % count) + count) % count;
    // `.at()` reads by index without the bracket-access pattern the
    // security linter flags; the wrapped index is always in range.
    const tab = PROJECT_SETTINGS_TABS.at(wrapped);
    if (!tab) return;
    // Switch first, focus second: when the unsaved-edits guard blocks the
    // switch, focus must stay on the still-selected tab instead of landing
    // on a tab that aria-selected says is not active.
    if (handleSectionChange(tab.id)) {
      tabButtonRefs.current.at(wrapped)?.focus();
    }
  };
  // Arrow-key navigation between tabs (APG automatic activation: moving
  // focus also selects the tab). Wired per-button rather than on the tablist
  // container so the handler always lives on a focusable element. Movement is
  // relative to the focused tab; if the dirty-guard blocks a switch, focus
  // stays on the selected tab, so the next keypress still starts from there.
  const onTabKeyDown = (event, fromIndex) => {
    if (event.key === 'ArrowRight') {
      event.preventDefault();
      focusTabAt(fromIndex + 1);
    } else if (event.key === 'ArrowLeft') {
      event.preventDefault();
      focusTabAt(fromIndex - 1);
    } else if (event.key === 'Home') {
      event.preventDefault();
      focusTabAt(0);
    } else if (event.key === 'End') {
      event.preventDefault();
      focusTabAt(PROJECT_SETTINGS_TABS.length - 1);
    }
  };

  /***
   * MARK: handleActiveProjectChange
   * @description Active-project switch guard: switching projects remounts the
   *   shared form (`key={activeProjectId}`), which would silently drop unsaved
   *   drafts — so with unsaved edits on a project-related tab, ask first,
   *   matching the tab-switch guard below. Re-selecting the current project
   *   never warns. Extra dropdown args `(value, option)` forward untouched to
   *   `selectProject`, mirroring the previous direct wiring.
   ***/
  const handleActiveProjectChange = (nextProjectId, ...rest) => {
    if (
      formDirty &&
      PROJECT_FORM_SECTIONS.includes(effectiveSection) &&
      nextProjectId !== activeProjectId &&
      typeof window !== 'undefined' &&
      typeof window.confirm === 'function' &&
      !window.confirm('You have unsaved changes. Switch projects anyway?')
    ) {
      return;
    }
    // Forward untouched (value, option): the previous wiring passed
    // `selectProject` straight to the dropdown, and callers rely on both.
    selectProject(nextProjectId, ...rest);
  };

  /***
   * MARK: handleSearchSelect
   * @description Jumps to a search result: switches to the entry's tab, then
   *   the highlight effect scrolls the target into view and rings it.
   *   Fail-safe: a malformed entry (unknown tab, missing element id) is
   *   ignored instead of switching tabs or highlighting nothing.
   ***/
  const handleSearchSelect = (entry) => {
    if (!entry || typeof entry !== 'object') return;
    if (
      !PROJECT_SETTINGS_SECTIONS.includes(entry.tab) ||
      typeof entry.elementId !== 'string' ||
      !entry.elementId
    ) {
      return;
    }
    // Only highlight when the switch actually happened: if the unsaved-edits
    // guard blocks it, the target is not on screen and ringing it (or a stale
    // element with the same id) would mislead.
    if (!handleSectionChange(entry.tab)) return;
    highlightSeqRef.current += 1;
    setHighlightTarget({ id: entry.elementId, at: highlightSeqRef.current });
  };

  // Scrolls the search target into view and highlights it briefly. Guarded
  // for test DOMs without `scrollIntoView`, and no-ops when the target id
  // is not on the active tab (e.g. a conditional field). Cleanup removes the
  // ring from the previous target: without this, picking a second result
  // while the first ring is still showing would clear the first hide timer
  // and leave that ring stuck on forever.
  useEffect(() => {
    if (!highlightTarget) return undefined;
    const targetId = highlightTarget.id;
    const clearRing = () => {
      const el = typeof document !== 'undefined' ? document.getElementById(targetId) : null;
      el?.classList?.remove('ring-2', 'ring-primary', 'rounded-sm');
    };
    const showTimer = setTimeout(() => {
      const el = typeof document !== 'undefined' ? document.getElementById(targetId) : null;
      if (el) {
        if (typeof el.scrollIntoView === 'function') {
          el.scrollIntoView({ behavior: 'smooth', block: 'center' });
        }
        el.classList.add('ring-2', 'ring-primary', 'rounded-sm');
      }
    }, HIGHLIGHT_SHOW_DELAY_MS);
    const hideTimer = setTimeout(clearRing, HIGHLIGHT_HIDE_DELAY_MS);
    return () => {
      clearTimeout(showTimer);
      clearTimeout(hideTimer);
      clearRing();
    };

import React from 'react';
import { useParams, useSearchParams, useNavigate } from 'react-router';
import { useKainBain } from '../../context/KainBainContext';
import { SystemSettingsContent } from './SystemSettingsContent';
import { SETTINGS_TABS } from './settingsTabs';
import { SYSTEM_SETTINGS_POPOUT_NAME } from './openSystemSettings';

const VALID_SECTION_IDS = new Set(SETTINGS_TABS.map((tab) => tab.id));
export const DEFAULT_SYSTEM_SETTINGS_SECTION = SETTINGS_TABS[0].id;

/***
 * MARK: SystemSettingsPage
 * @description Dedicated full-screen page for application-level System Settings
 * (`/system-settings` and `/system-settings/:section`). Renders SystemSettingsContent
 * with full-screen page chrome (back/close affordance, h1 title, and URL-driven
 * tab state for deep-linking and refresh persistence).
 * Distinct from project-scoped ProjectSettings (`/settings`): this screen is
 * application/platform scope, that one is per-project scope.
 * @example <SystemSettingsPage />
 ***/
export function SystemSettingsPage() {
  const { section } = useParams();
  const [searchParams] = useSearchParams();
  const navigate = useNavigate();
  const { setView } = useKainBain();

  // URL-driven tab state: route param /system-settings/:section wins, falling
  // back to ?section= query param, defaulting to the first tab. Unknown ids
  // fail safe to the first tab without rewriting the URL, so a typo'd deep
  // link still lands somewhere usable.
  const requestedSection = section || searchParams.get('section') || undefined;
  const effectiveSection =
    requestedSection && VALID_SECTION_IDS.has(requestedSection)
      ? requestedSection
      : DEFAULT_SYSTEM_SETTINGS_SECTION;

  const handleSectionChange = (sectionId) => {
    navigate(`/system-settings/${encodeURIComponent(sectionId)}`);
  };

  // True when this document is the popped-out settings window rather than the
  // main app tab: the primary affordance then closes the window instead of
  // navigating the shared history away from the board.
  const isPopout =
    typeof window !== 'undefined' &&
    Boolean(window.opener) &&
    window.name === SYSTEM_SETTINGS_POPOUT_NAME;

  const handleBack = () => {
    if (isPopout) {
      try {
        window.close();
        return;
      } catch {
        // window.close() can be refused (not script-opened); fall through.
      }
    }
    setView('orchestrator');
  };

  return (
    <article
      aria-label="System Settings"
      data-testid="system-settings-page"
      className="flex-1 flex flex-col h-full min-h-0 overflow-hidden bg-surface-deep"
    >
      <SystemSettingsContent
        activeSection={effectiveSection}
        onSectionChange={handleSectionChange}
        onBack={handleBack}
        backLabel={isPopout ? 'Close window' : 'Back to Board'}
        headingLevel="h1"
      />
    </article>
  );
}

export default SystemSettingsPage;

/***
 * MARK: System settings tabs
 * @description Single source of truth for the System Settings section tabs:
 *   id, label, and whether the settings footer's Reset control applies. The
 *   Notifications and UI panels persist immediately through their own
 *   controls (each with its own reset), so the footer Reset — which only
 *   restores the settings draft (+ Storage remount) — would be a misleading
 *   no-op there and is hidden. Every consumer (the SystemSettingsPage screen,
 *   SystemSettingsContent, unit tests, and the canary tab-bar suite) derives
 *   from this list so a new tab can never drift the expectations again.
 * @example SETTINGS_TABS.find((t) => t.id === 'ui') => { id: 'ui', label: 'UI', showFooterReset: false }
 ***/

export const SETTINGS_TABS = [
  { id: "harness", label: "Harness", showFooterReset: true },
  { id: "models", label: "Models", showFooterReset: true },
  { id: "engine", label: "Engine", showFooterReset: true },
  { id: "storage", label: "Storage", showFooterReset: true },
  { id: "notifications", label: "Notifications", showFooterReset: false },
  { id: "prompt-layout", label: "Prompt Layout", showFooterReset: false },
  { id: "ui", label: "UI", showFooterReset: false },
];

/***
 * MARK: SETTINGS_TAB_LABELS
 * @description Ordered tab labels derived from SETTINGS_TABS (render order).
 * @example SETTINGS_TAB_LABELS => ['Harness', 'Models', 'Engine', 'Storage', 'Notifications', 'UI']
 ***/
export const SETTINGS_TAB_LABELS = SETTINGS_TABS.map((tab) => tab.label);

/***
 * MARK: isFooterResetVisible
 * @description Whether the settings footer Reset applies to a section id.
 *   Unknown ids fail open (true) so a future tab without metadata keeps the
 *   legacy behaviour instead of silently losing its reset.
 * @example isFooterResetVisible('ui') => false
 * @param {string} sectionId - Active section id.
 * @returns {boolean} True when the footer Reset should render.
 ***/
export function isFooterResetVisible(sectionId) {
  if (typeof sectionId !== "string" || !sectionId) return true;
  const tab = SETTINGS_TABS.find((entry) => entry.id === sectionId);
  if (!tab) return true;
  return tab.showFooterReset !== false;
}

import React, { useState } from 'react';
import { useKainBain } from '../../context/KainBainContext';
import { Icon } from '../Icon';
import { FALLBACK_MODELS } from '../stageTypes';
import { useModelCatalog } from '../../hooks/useModelCatalog';
import { useModelRefreshSetting } from '../../hooks/useModelRefreshSetting';
import { HarnessSection } from './HarnessSection';
import { RunnersSection } from './RunnersSection';
import { StorageSection } from './StorageSection';
import { PushNotificationsSection } from './PushNotificationsSection';
import { PromptLayoutSection } from './PromptLayoutSection';
import { UiPreferencesPanel } from './UiPreferencesPanel';
import { MODEL_REFRESH_CONFIG_KEY } from './modelRefreshFlag';
import { SETTINGS_TABS, isFooterResetVisible } from './settingsTabs';

export const SYSTEM_SETTINGS_SECTIONS = SETTINGS_TABS.map(({ id, label }) => ({ id, label }));

export const DEFAULT_SYSTEM_SETTINGS_DRAFT = {
  defaultHarness: 'pi',
  stageTimeoutSecs: 600,
  allowPermissionBypass: false,
  defaultModel: '',
  fallbackModel: '',
  maxConcurrentTasks: 1,
  autoAdvanceStages: true,
  startComputeOnBoot: false,
};

/***
 * MARK: SettingRow
 * @description Label + control row used by the System Settings wireframe.
 * @example <SettingRow label="Default harness" hint="..."><select /></SettingRow>
 ***/
export function SettingRow({ label, hint, children }) {
  return (
    <div className="flex flex-col gap-1.5 py-3 border-b border-border-standard last:border-b-0">
      <span className="text-xs font-bold text-on-surface">{label}</span>
      {children}
      {hint && <span className="text-[11px] text-text-muted">{hint}</span>}
    </div>
  );
}

/***
 * MARK: SystemSettingsContent
 * @description Route- and shell-agnostic System Settings content component.
 * Renders header, tablist, all section panels (Harness, Models, Engine, Storage,
 * Notifications, Prompt Layout, UI), and footer actions. Rendered by the
 * standalone SystemSettingsPage screen (`/system-settings`); it takes no
 * modal state and never renders a dialog shell.
 * @param {Object} props
 * @param {string} [props.activeSection] - Controlled active tab id (e.g. from route).
 * @param {Function} [props.onSectionChange] - Callback when tab changes: (sectionId) => void.
 * @param {Function} [props.onClose] - Close callback (close button and Done button). The page leaves this unset and navigates via onBack instead.
 * @param {Function} [props.onBack] - Back callback (page back button and Done button fallback).
 * @param {string} [props.backLabel='Back to Board'] - Visible/accessible label for the back affordance. The page swaps it to "Close window" inside a popout.
 * @param {'h1'|'h2'} [props.headingLevel='h2'] - Level for the "System Settings" title.
 ***/
export function SystemSettingsContent({
  activeSection: controlledSection,
  onSectionChange,
  onClose,
  onBack,
  backLabel = 'Back to Board',
  headingLevel = 'h2',
}) {
  const { harnessPrefs, updateHarnessPref, resetHarnessPrefs } = useKainBain();

  const [internalActiveSection, setInternalActiveSection] = useState('harness');
  const activeSection = controlledSection ?? internalActiveSection;

  const setActiveSection = (sectionId) => {
    setInternalActiveSection(sectionId);
    onSectionChange?.(sectionId);
  };

  const [draft, setDraft] = useState(DEFAULT_SYSTEM_SETTINGS_DRAFT);

  // Live config gate and shared model catalogue hooks are enabled whenever this
  // content component is mounted.
  const { runtimeValue: modelRefreshRuntimeValue, enabled: modelRefreshEnabled } =
    useModelRefreshSetting(true);
  const {
    models,
    harnesses,
    refreshing: modelsRefreshing,
    refresh: refreshModels,
  } = useModelCatalog(FALLBACK_MODELS, { enabled: true });

  const [storageResetKey, setStorageResetKey] = useState(0);

  const update = (key, value) => setDraft((prev) => ({ ...prev, [key]: value }));
  const resetDraft = () => {
    setDraft(DEFAULT_SYSTEM_SETTINGS_DRAFT);
    setStorageResetKey((prev) => prev + 1);
  };

  const handleDone = () => {
    if (onClose) {
      onClose();
    } else if (onBack) {
      onBack();
    }
  };

  // Fail-safe section resolution: an unknown id falls back to the first tab.
  const effectiveSection = SYSTEM_SETTINGS_SECTIONS.some((section) => section.id === activeSection)
    ? activeSection
    : SYSTEM_SETTINGS_SECTIONS[0].id;

  const isDraftOnlySection = effectiveSection === 'models' || effectiveSection === 'engine';

  const showReset = isFooterResetVisible(effectiveSection);

  const inputClass =
    'w-full max-w-sm p-2 bg-surface-deep border border-border-standard rounded-sm text-sm text-on-surface outline-none focus:border-primary transition-colors';
  const toggleClass = 'flex items-center gap-2 cursor-pointer select-none text-xs text-on-surface';

  const HeadingTag = headingLevel === 'h1' ? 'h1' : 'h2';

  return (
    <>
      <header className="px-4 sm:px-6 py-3.5 sm:py-4 border-b border-border-standard bg-surface flex items-center justify-between shrink-0">
        <div className="flex items-center gap-3 min-w-0">
          {onBack && (
            <button
              type="button"
              onClick={onBack}
              aria-label={backLabel}
              className="px-3 py-1.5 min-h-[44px] bg-surface hover:bg-surface-container-high border border-border-standard rounded text-xs font-mono font-bold uppercase text-on-surface hover:text-primary transition-colors cursor-pointer flex items-center gap-1.5 shrink-0"
            >
              <span>←</span>
              <span>{backLabel}</span>
            </button>
          )}
          <div className="flex items-center gap-2 min-w-0">
            <span className="text-primary text-base select-none" aria-hidden="true">
              ⚙️
            </span>
            <HeadingTag
              id="system-settings-title"
              className="text-xs sm:text-sm font-bold uppercase tracking-wider text-on-surface font-label-caps truncate"
            >
              System Settings
            </HeadingTag>
          </div>
        </div>
        {onClose && (
          <button
            type="button"
            onClick={onClose}
            className="p-1 min-h-[44px] min-w-[44px] hover:bg-surface-container-high rounded text-text-muted hover:text-on-surface transition-colors flex items-center justify-center cursor-pointer shrink-0"
            aria-label="Close system settings"
          >
            <Icon name="close" />
          </button>
        )}
      </header>

      {/* shrink-0 invariant: bar never shrinks, the details pane scrolls */}
      <div
        role="tablist"
        aria-label="System settings sections"
        className="flex gap-1 px-4 sm:px-6 pt-3 bg-surface border-b border-border-standard overflow-x-auto shrink-0"
      >
        {SYSTEM_SETTINGS_SECTIONS.map((section) => (
          <button
            key={section.id}
            type="button"
            role="tab"
            aria-selected={effectiveSection === section.id}
            onClick={() => setActiveSection(section.id)}
            className={`px-3 py-2 min-h-[44px] text-xs font-bold uppercase tracking-wider rounded-t-sm transition-colors cursor-pointer whitespace-nowrap ${
              effectiveSection === section.id
                ? 'text-primary border-b-2 border-primary bg-surface-container-high'
                : 'text-text-muted hover:text-on-surface'
            }`}
          >
            {section.label}
          </button>
        ))}
      </div>

      <div className="flex-1 min-h-0 overflow-y-auto px-4 sm:px-6 py-2 custom-scrollbar bg-surface-deep">
        {isDraftOnlySection && (
          <p
            id="system-settings-wireframe-note"
            className="mt-3 px-3 py-2 text-[11px] font-mono text-text-muted bg-surface-container-high border border-border-standard rounded-sm"
          >
            Wireframe — changes here are not saved yet. Backend persistence lands in a later stage.
          </p>
        )}

        {effectiveSection === 'harness' && (
          <div role="tabpanel" aria-label="Harness settings">
            <HarnessSection
              draft={draft}
              update={update}
              inputClass={inputClass}
              toggleClass={toggleClass}

      toggleClass={toggleClass}
      prefs={harnessPrefs}
      updatePref={updateHarnessPref}
      resetPrefs={resetHarnessPrefs}
      onModelsRefresh={refreshModels}
      modelsRefreshing={modelsRefreshing}
      modelRefreshRuntimeValue={modelRefreshRuntimeValue}
    />
    <RunnersSection />
  </div>
)}

{effectiveSection === 'models' && (
  <div role="tabpanel" aria-label="Model settings">
    <div
      data-testid="model-catalogue"
      className="flex flex-col gap-2 py-3 border-b border-border-standard"
    >
      <span className="text-xs font-bold text-on-surface">Discovered models</span>
      <p data-testid="model-catalogue-count" className="text-[11px] text-text-muted">
        {models.length} models across {harnesses.length} harnesses in the shared catalogue.
      </p>
      {modelRefreshEnabled && (
        <button
          type="button"
          onClick={() => void refreshModels()}
          disabled={modelsRefreshing}
          className="self-start px-3 py-1.5 min-h-[44px] bg-surface-container-high hover:bg-surface-container-highest disabled:opacity-50 text-on-surface-variant text-[11px] font-bold uppercase tracking-widest rounded-sm transition-colors cursor-pointer disabled:cursor-default"
        >
          {modelsRefreshing ? 'Refreshing…' : 'Refresh models'}
        </button>
      )}
      {!modelRefreshEnabled && (
        <p
          data-testid="model-refresh-disabled-note"
          className="text-[11px] text-text-muted"
        >
          Model refresh is disabled by the {MODEL_REFRESH_CONFIG_KEY} setting.
        </p>
      )}
    </div>
    <SettingRow
      label="Default model"
      hint="Model reference for new stages, e.g. harness::provider::id."
    >
      <input
        type="text"
        aria-label="Default model"
        placeholder="e.g. pi::ollama-cloud::glm-5.3-flash"
        value={draft.defaultModel}
        onChange={(e) => update('defaultModel', e.target.value)}
        className={inputClass}
      />
    </SettingRow>
    <SettingRow label="Fallback model" hint="Used when the default model is unavailable.">
      <input
        type="text"
        aria-label="Fallback model"
        placeholder="e.g. pi::ollama-cloud::glm-4.6"
        value={draft.fallbackModel}
        onChange={(e) => update('fallbackModel', e.target.value)}
        className={inputClass}
      />
    </SettingRow>
  </div>
)}

{effectiveSection === 'engine' && (
  <div role="tabpanel" aria-label="Engine settings">
    <SettingRow
      label="Max concurrent tasks"
      hint="How many tasks the compute engine may run at once."
    >
      <input
        type="number"
        aria-label="Max concurrent tasks"
        min={1}
        max={16}
        value={draft.maxConcurrentTasks}
        onChange={(e) => update('maxConcurrentTasks', Number(e.target.value))}
        className={inputClass}
      />
    </SettingRow>
    <SettingRow label="Stage flow" hint="Advance stages automatically when gates pass.">
      <label className={toggleClass}>
        <input
          type="checkbox"
          checked={draft.autoAdvanceStages}
          onChange={(e) => update('autoAdvanceStages', e.target.checked)}
          className="rounded-sm bg-surface-deep border-border-standard text-primary focus:ring-0 cursor-pointer"
        />
        <span>Auto-advance stages</span>
      </label>
    </SettingRow>
    <SettingRow label="Boot behaviour" hint="Start the compute engine when the app boots.">
      <label className={toggleClass}>
        <input
          type="checkbox"
          checked={draft.startComputeOnBoot}
          onChange={(e) => update('startComputeOnBoot', e.target.checked)}
          className="rounded-sm bg-surface-deep border-border-standard text-primary focus:ring-0 cursor-pointer"

                  className="rounded-sm bg-surface-deep border-border-standard text-primary focus:ring-0 cursor-pointer"
                />
                <span>Start compute on boot</span>
              </label>
            </SettingRow>
          </div>
        )}

        {effectiveSection === 'storage' && (
          <div role="tabpanel" aria-label="Storage settings">
            <StorageSection key={storageResetKey} />
          </div>
        )}

        {effectiveSection === 'notifications' && (
          <div role="tabpanel" aria-label="Notification settings">
            <PushNotificationsSection />
          </div>
        )}

        {effectiveSection === 'prompt-layout' && (
          <div role="tabpanel" aria-label="Prompt Layout settings">
            <PromptLayoutSection />
          </div>
        )}

        {effectiveSection === 'ui' && (
          <div role="tabpanel" aria-label="UI settings">
            <UiPreferencesPanel onOpenPushNotifications={() => setActiveSection('notifications')} />
          </div>
        )}
      </div>

      <footer className="px-4 sm:px-6 py-3 border-t border-border-standard bg-surface flex justify-between items-center gap-2 shrink-0">
        {showReset ? (
          <button
            type="button"
            onClick={resetDraft}
            className="px-4 py-2 min-h-[44px] bg-surface-container-high hover:bg-surface-container-highest text-on-surface-variant text-xs font-bold uppercase tracking-widest rounded-sm transition-colors cursor-pointer"
          >
            Reset
          </button>
        ) : (
          <span className="text-[11px] text-text-muted">
            Changes save automatically in this section.
          </span>
        )}
        <button
          type="button"
          onClick={handleDone}
          className="px-6 py-2 min-h-[44px] bg-primary text-on-primary text-xs font-bold uppercase tracking-widest rounded-sm hover:brightness-110 transition-all active:scale-95 cursor-pointer"
        >
          Done
        </button>
      </footer>
    </>
  );
}

