   ***/
  const probeHarness = useCallback(
    async (id, { refresh = false } = {}) => {
      if (!id || typeof api.getHarnessModels !== 'function') return;
      setRefreshingIds((prev) => (prev.includes(id) ? prev : [...prev, id]));
