      const list = Array.isArray(res?.reliability) ? res.reliability : [];
      const byId = {};
      for (const entry of list) {
        if (entry?.harnessId) byId[entry.harnessId] = entry;
      }
      setReliabilityById(byId);
    } catch {
      setReliabilityError(true);
    }
